import math

def wrap(a):
    while a > 180: a -= 360
    while a < -180: a += 360
    return a

mode = 'rev'
last_aim = 0.0
n = 0
HW = 1.25

def free_len(a, pts):
    f = 9.0
    for (r, d) in pts:
        rel = math.radians(r - a)
        al = d * math.cos(rel)
        lat = d * math.sin(rel)
        if al > 0 and abs(lat) < HW:
            f = min(f, al)
    return f

def control(obs):
    global mode, last_aim, n
    n += 1
    h = obs.get('hitch_deg', 0.0)
    views = obs.get('views') or {}
    cam = views.get('camera')
    axis = 180.0 - h
    if cam:
        axis = cam.get('axis_deg', axis)
        pts = []
        for w in cam.get('walls', []) or []:
            try:
                pts.append((wrap(w[0] - axis), float(w[1])))
            except Exception:
                pass
        corners = []
        for c in cam.get('target_corners', []) or []:
            try:
                corners.append((float(c[0]), float(c[1])))
            except Exception:
                pass
        aim = None
        if len(corners) >= 2:
            o = cam.get('origin', [0, 0])
            xs = [c[1] * math.cos(math.radians(c[0])) for c in corners]
            ys = [c[1] * math.sin(math.radians(c[0])) for c in corners]
            cb = math.degrees(math.atan2(sum(ys) / len(ys), sum(xs) / len(xs)))
            aim = wrap(cb - axis)
        if aim is None:
            best = None; bs = -1e9
            for a in range(-60, 61, 3):
                s = free_len(a, pts) - 0.02 * abs(a) - 0.01 * abs(a - last_aim)
                if s > bs:
                    bs = s; best = a
            aim = float(best)
        last_aim = 0.6 * last_aim + 0.4 * aim
    aim = last_aim
    hdes = max(-30.0, min(30.0, -0.9 * aim))
    if mode == 'rev' and abs(h) > 45:
        mode = 'fwd'
        wake('hitch %.0f, pulling forward' % h)
    if mode == 'fwd' and abs(h) < 8:
        mode = 'rev'
    if mode == 'fwd':
        steer = 0.0
        spd = 1.2
    else:
        steer = max(-34.0, min(34.0, 2.2 * (h - hdes)))
        spd = -1.0
    if n % 20 == 0:
        print('t=%.1f h=%.1f aim=%.1f hdes=%.1f st=%.1f mode=%s' % (obs.get('t', 0), h, aim, hdes, steer, mode))
    return (steer, spd, -23.0)

