import math
L1=2.5; L2=3.6; A=1.3
X=0.0; Y=0.0; PSI=0.0
pts={}
T=None
mode='rev'
GZ=[150,64,-64,-150,-64,64]
gi=0
hold=0.0
n=0
warned=False

def tow(px,py):
    c=math.cos(PSI); s=math.sin(PSI)
    return (X+c*px-s*py, Y+s*px+c*py)

def addview(v):
    ox,oy=v['origin']
    for w in v.get('walls',[]) or []:
        b=math.radians(w[0]); d=w[1]
        if d>14: continue
        wx,wy=tow(ox+d*math.cos(b), oy+d*math.sin(b))
        pts[(round(wx/0.25),round(wy/0.25))]=(wx,wy)

def clip(a,lo,hi):
    return max(lo,min(hi,a))

def control(obs):
    global X,Y,PSI,T,mode,gi,hold,n,warned
    n+=1
    dt=obs.get('dt',0.1)
    m=obs['motion']; v=m['v_mps']
    st=math.radians(obs['steer_deg'])
    X+=v*math.cos(PSI)*dt; Y+=v*math.sin(PSI)*dt
    PSI+=v*math.tan(st)/L1*dt
    views=obs.get('views') or {}
    for k,vw in views.items():
        if vw: addview(vw)
    tg=obs.get('target') or {}
    rig=obs['rig']
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        ex,ey=rig['eye']
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tw=tow(ex+d*math.cos(b), ey+d*math.sin(b))
        if T is None: T=tw
        else: T=(0.8*T[0]+0.2*tw[0],0.8*T[1]+0.2*tw[1])
    # head
    hd=obs['head']
    look=GZ[gi]
    if abs(hd['gaze_deg']-look)<2 and hd.get('settled'):
        hold+=dt
        if hold>=0.4:
            gi=(gi+1)%len(GZ); hold=0.0; look=GZ[gi]
    phi=math.radians(obs['hitch_deg'])
    hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    R=tow(rx,ry)
    bv=math.atan2(ry-hy,rx-hx)+PSI
    if mode=='fwd':
        if abs(obs['hitch_deg'])<8:
            mode='rev'
        else:
            return (clip(-obs['hitch_deg']*1.0,-35,35), 0.8, look)
    if abs(obs['hitch_deg'])>45 or obs.get('status')=='JACKKNIFED':
        mode='fwd'
        return (clip(-obs['hitch_deg'],-35,35),0.8,look)
    # choose direction
    near=[p for p in pts.values() if (p[0]-R[0])**2+(p[1]-R[1])**2<144]
    best=None; res=[]
    for ad in range(-55,60,5):
        a=bv+math.radians(ad)
        ca=math.cos(a); sa=math.sin(a)
        free=9.0
        for (px,py) in near:
            dx=px-R[0]; dy=py-R[1]
            t=dx*ca+dy*sa
            if t<=-0.3 or t>=free: continue
            l=-dx*sa+dy*ca
            if abs(l)<1.5:
                free=max(t,0.0)
        res.append((ad,free))
    mx=max(f for a,f in res)
    good=[a for a,f in res if f>=0.85*mx]
    e=math.radians(sum(good)/len(good))
    if T is not None:
        dx=T[0]-R[0]; dy=T[1]-R[1]; dd=math.hypot(dx,dy)
        along=dx*math.cos(bv)+dy*math.sin(bv)
        if dd<7 and along>1.5:
            et=math.atan2(dy,dx)-bv
            et=(et+math.pi)%(2*math.pi)-math.pi
            e=0.3*e+0.7*et
        elif along<=1.5 and dd<4:
            e=0.0
    phid=clip(-1.2*e,-math.radians(35),math.radians(35))
    k=1.5
    tn=L1*(math.sin(phi)/L2+k*(phi-phid))/(1+A*math.cos(phi)/L2)
    steer=clip(math.degrees(math.atan(tn)),-45,45)
    sp=-0.9
    if abs(phi-phid)>math.radians(15): sp=-0.6
    rem=obs['progress']['remaining']
    if rem<-3 and not warned:
        warned=True; wake('passed bay centre by 3m, not ended')
    if n%20==0:
        print('t%.1f phi%.0f phid%.0f e%.0f mx%.1f st%.0f pts%d T%s rem%.1f'%(obs['t'],math.degrees(phi),math.degrees(phid),math.degrees(e),mx,steer,len(pts),'y' if T else 'n',rem))
    return (steer,sp,look)

