            if fr<0.7: s=max(s,15)
            if fl<0.6: s=min(s,-10)
            return (s,0.5,look)
    if abs(hdeg)>62 or obs.get('status')=='JACKKNIFED':
        mode='fwd'
        wake('pulling forward hitch%.0f fl%.1f fr%.1f'%(hdeg,fl,fr))
        return (clip(-hdeg,-35,35),0.5,look)
    if fr<0.3 and fl>0.6:
        mode='shunt'; esc_d=0.0
        wake('shunt fwd: nose near right rail fr%.2f hitch%.0f'%(fr,hdeg))
        return (45.0,0.0,look)
    if abs(v)<0.03 and (m.get('hold_s') or 0)<=0:
        stuck+=dt
        if stuck>2.0:
            mode='stop'; stuck=0.0
            wake('stuck reversing fl%.1f fr%.1f hitch%.0f'%(fl,fr,hdeg))
            return (obs['steer_deg'],0.0,look)
    else:
        stuck=0.0
    phi=math.radians(hdeg)
    hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    R=tow(rx,ry)
    bv=math.atan2(ry-hy,rx-hx)+PSI
    ca=math.cos(bv); sa=math.sin(bv)
    stations=[0.5,2.5,4.5]
