        if abs(dx)>8 or abs(dy)>8: continue
        u=dx*ca+dy*sa; w=-dx*sa+dy*ca
        if -2.5<u<2.0:
            if w>0: cp=min(cp,math.hypot(max(u,0),w-1.2) if w>1.2 else max(u,0))
            else: cm=min(cm,math.hypot(max(u,0),-w-1.2) if w<-1.2 else max(u,0))
        if abs(w)>5: continue
        for s in stations:
            if abs(u-s)<1.0:
                if w>0:
                    if side[s][0] is None or w<side[s][0]: side[s][0]=w
                else:
                    if side[s][1] is None or w>side[s][1]: side[s][1]=w
    es=[]
