        dx=T[0]-R[0]; dy=T[1]-R[1]; dd=math.hypot(dx,dy)
        along=dx*ca+dy*sa
        if dd<7 and along>1.5:
            et=math.atan2(-dx*sa+dy*ca,along)
            e=0.3*e+0.7*et; endp=True
        elif along<=1.5 and dd<4:
            e=0.0; endp=True
    if ef is None: ef=e
    ef+=clip(e-ef,-0.04,0.04)
    lim=math.radians(15 if endp else 45)
    phid=clip(-1.3*ef,-lim,lim)
    rem=obs['progress']['remaining']
    if rem>22 and not endp and cm>0.8: phid=max(phid,math.radians(10))
    k=1.5
    tn=L1*(math.sin(phi)/L2+k*(phi-phid))/(1+A*math.cos(phi)/L2)
    steer=clip(math.degrees(math.atan(tn)),-45,45)
    capr=clip(45*(fr-0.35),-10,45)
    capl=clip(45*(fl-0.25),-10,45)
